function styleControls(root=document){
  const primary=new Set(['scene-save','binding-save','scene-name-save','scene-activate','binding-add','wifi-save']);
  root.querySelectorAll('button').forEach(b=>{if(b.matches('.nav-link,.scene-tab,.binding-edit,.dropdown-control,.dropdown-option'))return;b.classList.add('btn','btn-sm');b.classList.add(b.classList.contains('danger')?'btn-outline-danger':primary.has(b.id)?'btn-primary':'btn-outline-secondary')});
  root.querySelectorAll('select').forEach(el=>el.classList.add('form-select','form-select-sm'));
  root.querySelectorAll('input').forEach(el=>{if(el.type==='checkbox')el.classList.add('form-check-input');else if(el.type==='range')el.classList.add('form-range');else {el.classList.add('form-control','form-control-sm');if(el.type==='color')el.classList.add('form-control-color')}});
  Dropdowns.enhance(root);
}

