async function pollLog(force=false){
  if(logBusy||!$('log-details').open||(!force&&(document.hidden||$('device').hidden||logPaused)))return;
  logBusy=true;
  try{
    const data=await request('/api/log'+(logCursor===null?'':'?after='+logCursor));
    if(logBoot!==null&&logBoot!==data.boot&&logCursor!==null){logBoot=data.boot;logCursor=null;logText='';$('log-view').textContent='Device restarted; loading recent log…';return}
    logBoot=data.boot;logCursor=data.next;
    if(data.reset)logText+='\n[Older log entries overwritten]\n';
    logText=(logText+data.text).slice(-12000);
    const view=$('log-view'),follow=view.scrollHeight-view.scrollTop-view.clientHeight<24;
    view.textContent=logText||'No log entries yet.';
    if(follow)view.scrollTop=view.scrollHeight;
    $('log-state').textContent=(logPaused?'Paused':'Live')+' ('+data.capacity+' byte RAM buffer)'+(data.next!==data.total?', loading backlog':'');
  }catch(e){$('log-state').textContent='Could not read log: '+e.message}
  finally{logBusy=false}
}
