function renderTimezones(zones,selected){
  const regions={America:'Americas',Asia:'Asia',Europe:'Europe',Australia:'Oceania',Pacific:'Oceania'};
  const groups=new Map();
  const fixed=z=>z.id==='Etc/UTC'||/^UTC[+-]/.test(z.id);
  const offset=z=>{if(z.id==='Etc/UTC')return 0;const [,sign,hours,minutes]=z.id.match(/^UTC([+-])(\d{2}):(\d{2})$/);return (sign==='-'?-1:1)*(Number(hours)*60+Number(minutes))};
  for(const zone of zones){
    const region=zone.id.split('/')[0];
    const name=fixed(zone)?'UTC offsets':regions[region]||region.replaceAll('_',' ');
    if(!groups.has(name))groups.set(name,[]);
    groups.get(name).push(zone);
  }
  const names=[...groups.keys()].sort((a,b)=>a==='UTC offsets'?1:b==='UTC offsets'?-1:a.localeCompare(b));
  $('timezone').replaceChildren(...names.map(name=>{
    const group=document.createElement('optgroup');group.label=name;
    const choices=groups.get(name).sort(name==='UTC offsets'?(a,b)=>offset(a)-offset(b):(a,b)=>a.label.localeCompare(b.label));
    group.append(...choices.map(z=>option(z.label,z.id)));
    return group;
  }));
  $('timezone').value=selected;
}
