function allBindingInputs(){const keys=[...cfg.catalog.inputs],buttons=cfg.catalog.combo_inputs||[];for(let mask=1;mask<(1<<buttons.length);mask++)if(mask&(mask-1)){const members=buttons.filter((_,i)=>mask&(1<<i));keys.push(members.join('+'));for(const modifier of members)keys.push(modifier+'>'+members.filter(k=>k!==modifier).join('+'))}return keys}
