async function deleteBinding(b){if(sceneBusy||!confirm('Delete '+text(b.input)+' ('+eventText(b.gesture)+') and its commands?'))return;if(await sceneCommand({op:'binding',scene_id:selectedScene,input:b.input,gesture:b.gesture,count:0}))renderScenes()}
async function poll(){if(polling)return;polling=true;try{state=await request('/api/status');const h=state.hardware,s=state.scene;renderGeneral();renderBluetooth();$('connection').textContent=[(h.ready?'Ready':state.recovery_mode?'Recovery mode':'Starting…')+' ('+state.firmware.split('-')[0]+')',state.wifi.ip].join('\n');$('connection').title=state.firmware;const wifi=state.wifi;$('wifi-live-ssid').textContent=wifi.ssid||wifi.stored_ssid||'—';$('wifi-live-status').textContent=wifi.connected?'Connected':'Disconnected';$('wifi-live-status').className=wifi.connected?'ok':'bad';$('wifi-live-rssi').textContent=wifi.connected?wifi.rssi+' dBm':'—';$('wifi-live-ip').textContent=wifi.connected?wifi.ip:'—';$('active-scene').textContent=s.name;$('active-scene').title=s.name;$('scene-live').textContent='Standby screen: '+text(s.standby_screen);$('usb-status').textContent=state.usb.active_mode==='ethernet'?(state.usb.link_up?'Network connected':'Waiting for USB host'):'Serial + JTAG';renderLighting();generalLevelHints();if(!generalLoaded){$('wifi').elements.ssid.value=state.wifi.stored_ssid;generalLoaded=true}if($('binding-dialog').open)syncEditorControls();const e=s.last_event;$('last-event').textContent=e.sequence?'Last input: '+text(e.input)+' ('+text(e.gesture)+') → '+text(e.action)+(e.percent>=0?' ('+e.percent+'%)':''):'Last input: none';$('last-event').title=$('last-event').textContent;$('scene-live').title=$('scene-live').textContent;$('checks').textContent='PSRAM '+(h.psram.test_passed?'passed':'not verified')+', LED errors '+h.leds.errors+', audio I/O errors '+h.audio.io_errors;if(!$('device').hidden&&$('telemetry-details').open)$('telemetry').textContent=JSON.stringify(state,null,2);if(cfg&&(cfg.state.epoch!==s.epoch||cfg.state.revision!==s.revision)&&!sceneBusy&&!dirty&&!sceneSettingsDirty&&!$('binding-dialog').open&&!$('scene-name-dialog').open){cfg=await request('/api/scenes');if(!scene())selectedScene=cfg.state.active;renderScenes()}}catch(e){$('wifi-live-status').textContent='Unavailable';$('wifi-live-status').className='bad';$('wifi-live-rssi').textContent=$('wifi-live-ip').textContent='—';$('connection').textContent='Device unavailable: '+e.message;$('connection').title=$('connection').textContent}finally{polling=false}}
